    internal static ExprRow ReadExprRow(IReadNode node)
    {
        return node.Label switch
        {
            "AddIntegerRow" => new ExprRow(ReadAddIntegerRow(node)),
            "SubtractIntegerRow" => new ExprRow(ReadSubtractIntegerRow(node)),
            "MultiplyIntegerRow" => new ExprRow(ReadMultiplyIntegerRow(node)),
            "IntegerDivideIntegerRow" => new ExprRow(ReadIntegerDivideIntegerRow(node)),
            "ModuloIntegerRow" => new ExprRow(ReadModuloIntegerRow(node)),
            "FloorIntegerRow" => new ExprRow(ReadFloorIntegerRow(node)),
            "CeilingIntegerRow" => new ExprRow(ReadCeilingIntegerRow(node)),
            "RoundWithDigitsIntegerRow" =>
                new ExprRow(ReadRoundWithDigitsIntegerRow(node)),
            "RoundWithoutDigitsIntegerRow" =>
